\label{def:imm}
Let $p$ be a prime,  $ G $ be a group, $ H <G $, and $ V $ be a $ \mathrm{GF}(p)G $-module.
We say that the triple $ (G,H,V) $ is \emph{immutable} if and only if $ G $ and $ H $ have exactly the same orbits on $ V $.

\label{Cor:Main Result} Suppose that $G$ is quasisimple, $K <G$, $V$ is a non-trivial irreducible $\mathrm{GF}(2)G$-module and $(G,K,V)$ is immutable.  Then, either, $K$ acts transitively on the non-zero vectors of $V$, or one of the following holds:
 \begin{enumerate}
 \item $G \cong \Omega_{2n}^-(2^a)$ with $n \ge 3$ odd,  $V$ is the natural $\mathrm{GF}(2)G$-module, $K \cong \mathrm{SU}_{n}(2^a)$ and $(G,N_G(K),V)$ is as in \cref{Main theorem} (i).

  \item $ G \cong \Omega_{2n}^+(2^a) $ with $ n \ge 6 $ even, $V$ is the natural $\mathrm{GF}(2)G$-module,
   $K \cong \mathrm{SU}_{n}(2^a)$ and $(G,N_G(K),V)$ is as in \cref{Main theorem} (ii).
 \item $G \cong \Omega_{2n}^\epsilon(2^a)$ with $n \ge 5$ and $\epsilon 1 =(-1)^n$,  $V$ is the natural $\mathrm{GF}(2)G$-module, $K \cong \mathrm{SU}_{n}(2^a)$ and $(G,N_G(K),V)$ is as in \cref{Main theorem} (i) or (ii).
 \item $G \cong \mathrm{Sp}_6(2^a)$, $V$ is the spin $\mathrm{GF}(2)G$-module, $K \cong \mathrm{SU}_4(2^a)$, and  $(G,N_G(K),V)$ is as in \cref{Main theorem} (iv).
 \item $G= \Omega_8^+(2^a)$,  $a\ge 2$, $V$ is the natural $\mathrm{GF}(2)G$-module and either
 \begin{enumerate} \item $K \cong \mathrm{Sp}_6(2^a)$ is maximal in $G$  (two conjugacy classes);
 \item $K \le L$ with $K \cong \mathrm{SU}_4(2^a)$  and  $L \cong \mathrm{Sp}_6(2^a)$ as in (a), and $N_G(K)$ is maximal in $G$ with $N_G(K) \cong \mathrm{GU}_4(2^a){:}2$ and $|N_G(K):N_L(K)|=2^a+1$ (two conjugacy classes).
 \end{enumerate}
 \item $G \cong \Omega_8^+(2)$,  $V$ is the natural $\mathrm{GF}(2)G$-module and either
 \begin{enumerate}
 \item $K \cong \mathrm{Sp}_6(2)$ is maximal in $G$  (two conjugacy  classes);
 \item $K \cong \mathrm{SU}_4(2)$, $K \le L \cong\mathrm{Sp}_6(2)$, $N_G(K) \cong \mathrm{GU}_4(2){:}2$ is maximal in $G$ with $|N_G(K): N_L(K)|=3$  (two conjugacy classes); or
 \item $K \cong \mathrm{Alt}(9)$ is maximal in $G$  (two conjugacy classes).
\end{enumerate}
\item $G \cong \mathrm{Alt}(9)$, $V$ is the fully deleted permutation $\mathrm{GF}(2)G$-module,  and $K \cong \mathrm{PSL}_2(8)$ or $\mathrm P \Gamma \mathrm L_2(8)$ (two conjugacy classes).
\end{enumerate}

\label{thm:Theorem B}
Suppose that $G$ is a quasisimple group, $H$ is a maximal subgroup of $G$, and $V$ is a $\mathrm{GF}(2)G$-module.
Assume that $V$ has no centralized direct summand and that $(G,H,V)$ is immutable.
Then either $V$ is irreducible and $(G,H,V)$ is as in \cref{Main theorem}, or one of the following holds:
\begin{enumerate}
  \item $G = \mathrm{Sp}_{2n}(2^a)$, $n \ge 3$,  $V$ is a faithful section of $\mathcal W(\mathrm{Sp}_{2n}(2^a))$ and either
   \begin{enumerate}\item$H \cong \mathrm{Sp}_{2n/b}(2^{ab}){:}b$ for some odd prime $b$ dividing $n$, or \item $2n = 6$ and $H \cong \mathrm{G}_2(2^a)$.
    \end{enumerate}
  \item $G = \mathrm{Sp}_{2n}(2^a)$, $n \ge 2$ even, $(n,2^a) \neq (2,2)$, $H = \mathrm{Sp}_n(2^{2a}){:}2$, and for $\mathcal W = \mathcal W(\mathrm{Sp}_{2n}(2^a))$ and each $B \le C_{\mathcal W}(G)$, there exists a uniquely determined submodule
  $[ \mathcal W, G ] \le B^\dagger \le \mathcal W$ with $\dim B^\dagger / B = a(2n+1)$ such that the faithful section $V = A/B$ satisfies $(G,H,V)$ is immutable if and only if $[V,G] \le A \le B^\dagger$.
  \item $G = \mathrm{SL}_4(2) \cong \mathrm{Alt}(8)$, $H = \mathrm{Alt}(7)$, and $V$ is a direct sum of at most three irreducible $4$-dimensional modules for $G$.
  \item $G = \mathrm{Alt}(6) = \mathrm{Sp}_4(2)'$, $H = \mathrm{SL}_2(4) \cong \mathrm{Alt}(5)$, and $V$ is the $5$-dimensional $\Omega_5(2)$-module or its dual restricted to $G$.
\end{enumerate}

\label{lem:reg orb compendium}
Suppose that $(G,H,V)$ is immutable. Then the following hold:
\begin{enumerate}
\item $G$ does not have a regular orbit on $V$.
\item There exists $v \in V^\#$ with $|G:C_G(v)|$ prime to $p$ and $G=C_G(v)H$.
\item  For $G > L > H$, $(G,H,V)$ is immutable if and only if $(L,H,V|_L)$ and $(G,L,V)$ are immutable.
\end{enumerate}

\label{lem:dimbound}
  Let  $G$ be  a      quasisimple  group  and  $V$ a  faithful  irreducible $\mathrm{GF}(p)G$-module.
 If $G$  has no regular orbits on V, then $|V| \le |G|^{\alpha(G)}$.

\label{lem: reduct to irred}   Suppose that $(G,H,V)$ is immutable and $W$ is a submodule of $V$. Then
 \begin{enumerate}
 \item  $(G ,H  ,W)$ is immutable; and
\item $(G,H  ,V/W)$ is immutable.
\end{enumerate}
In particular, if $U/W$ is a section of $V$, then $(G,H,U/W)$ is immutable.

\label{lem:vec stabiliser}
Suppose that $G$ is a group and $V$ is a $\mathrm{GF}(p)G$-module.
Let $W$ be a proper  submodule of $V$ and $v+W$ be an element of $V/W$. Let $P$ be the stabilizer in $G$ of $v+W$ and assume that $v$ can be chosen in $C_V(P)$. Then, for $w \in W$, $C_G(v+w)=C_P(w)$.

\label{lem:alt cases}
Suppose that $F^*(G)$ is a covering group of $\mathrm{Alt}(n)$, with $n \ge 5$. Assume that $H \ne F^*(G)$. Then   $V$ is either the fully deleted permutation module for $G$ or we have one of the following cases:
\begin{enumerate}
\item $n=7$, $\dim V= 4$ and $(G,H,V)$ is one of $(\mathrm{Alt}(7), \mathrm{Sym}(5), V)$  or $(\mathrm{Alt}(7),\mathrm{Alt}(6),V)$. Furthermore, $H$ acts transitively on $V^\#$.
 \item $n=8$, $\dim V=4$ and $(G,H,V) $ is one of $(\mathrm{Alt}(8),\mathrm{Alt}(7),V)$, $(\mathrm{Alt}(8),\mathrm{Sym}(6),V)$, $(\mathrm{Alt}(8),(3\times \mathrm{Alt}(5)).2,V)$. Furthermore, $H$ acts transitively on $V^\#$.
 \item $n=8$, $\dim V=8$ and $(G,H,V)= (\mathrm{Sym}(8),\mathrm{Sym}(7),V)$. Furthermore, $G$ has three orbits on $V^\#$ and they have lengths $30$, $105$, $120$.
\end{enumerate}

\label{lem:Orbs del mod} Suppose that $X \cong \mathrm{Sym}(n)$ or $\mathrm{Alt}(n)$ with $n \ge 5$ and $W$ is the $\mathrm{GF}(2)X$-permutation module  with permuted basis $\Omega=\{e_1, \dots, e_n\}$. Let $V \cong W_1/(W_0\cap W_1)$ be the fully deleted permutation module for $X$. Then
\begin{enumerate}
\item the group $X$ has $n$ orbits on  $W$ with orbit representatives $\sum_{i=1}^ke_i$ for $1 \le k \le n$;
\item the orbits of $X$ on $W_0$ have representatives   $\sum_{i=1}^ke_i$ for $1 \le k \le n$ with $k$ even; and
\item if $n$ is even, then the orbits of $X$ on $V$  have representatives $\sum_{i=0}^{k} e_i+W_0$ with $k$ even and $0\le k \le n/2$.
\end{enumerate}

\label{lem:full deleted}
Suppose that $( G,H,V)$ is   immutable  with $F^*(G) \cong \mathrm{Alt}(n)$, $n \ge 9$ and $V$ the fully deleted permutation module. Then
 $n=9$, $G \cong \mathrm{Alt}(9)$,   $H\cong \mathrm P\Gamma\mathrm L_2(8)$ (two conjugacy classes) and $\dim V=8$. Furthermore, if $G\cong \mathrm{Alt}(9)$, then its orbits on $V^\#$ have lengths  $9$, $36$, $84$, and $126$.

\label{small:alt}
Suppose that $V$ is the fully deleted permutation module for $G$ with $F^*(G) \cong \mathrm{Alt}(n)$, $5\le n \le 8$. Suppose that $H$ is a maximal subgroup of $G$, with $H \ne F^*(G)$.

Then $(G,H,V)$ is immutable if and only if $(G,H,V)$ is one of the following:
\begin{enumerate} \item $(\mathrm{Sym}(5),\mathrm{Frob}(20),V)$, with orbits of length $5$ and $10$ on $V^\#$; \item $(\mathrm{Alt}(6),\mathrm{SL}_2(4),V)$ with $G$ transitive on $V^\#$;
 or \item $(\mathrm{Sym}(6),\Gamma\mathrm L_2(4),V)$ with $G$ transitive on $V^\#$.
\end{enumerate}

\label{hypss7} \cref{hyp} holds and for $q=2^a$,   $G$ is a central quotient of one of
\begin{enumerate}
 \item $\mathrm{SL}_m(q)$, with $m \ge 2$ and $(m,q) \ne (2,2)$;
  \item $\mathrm{SU}_m(q)$ with $m \ge 3$ and $(m,q) \ne (3,2)$;
  \item $\mathrm{Sp}_{m}(q)$, $m \ge 4$ even and $(m,q) \ne (4,2)$; or
  \item $\Omega_{m}^+(q)$  or $\Omega_{m}^-(q)$ with $m \ge 8$ even.
   \end{enumerate}

\label{the new list} Assume \cref{hypss7} with $m \ge 3$.    Then
there is a subset $\Theta \subseteq \Sigma$ and a basic irreducible $\overline{\mathbb L}$-module $\overline{W}$ such that
$$\overline{V}= \bigotimes_{\theta \in \Theta} \overline{W}^{\theta}$$
where the possibilities for $G$ and $\overline{W}$ are described as follows.
\begin{enumerate}
\item \cref{prop:char2 list} (i) or (ii) holds, $G/Z(G)=\mathrm{PSL}_m(q)$ with $m \ge 3$  and either\begin{enumerate} \item $\overline{W}=V(\omega_1)$ is the natural $m$-dimensional $\overline{\mathbb L}G$-module; or\item $\overline{W}=V(\omega_{m-1})$ is the dual natural $m$-dimensional $\overline{\mathbb L}G$-module in (i)(a).\end{enumerate}
\item \cref{prop:char2 list} (iii), (iv) or (x) holds, $G = \mathrm{Sp}_{2n}(q)$ with $n \ge 2$,    and  either\begin{enumerate} \item $\overline{W}=V(\omega_1)$ is the natural $2n$-dimensional $\overline{\mathbb L}G$-module; or\item $\overline{W}=V(\omega_{n})$ is the $2^n$-dimensional spin  $\overline{\mathbb L}G$-module.\end{enumerate}
\item \cref{prop:char2 list} (v) holds, $G/Z(G)= \mathrm{PSU}_{2n}(q)$ with $n \ge 2$,  and $\overline{W}= V(\omega_n)$ is the  $n$th  exterior square of the natural $\overline{\mathbb L}\mathrm{SU}_{2n}(q)$-module.
\item   \cref{prop:char2 list} (vi) or (ix) holds, $G = \Omega_{2n}^\epsilon(q)$ with $n \ge 5$, $\epsilon 1= (-1)^n$,   and $\overline{W}= V(\omega_1)$ is the natural $\overline{\mathbb L}G$-module.
\item   \cref{prop:char2 list} (vii) or (viii) holds, $G = \Omega_{2n}^+(q)$ with $n \ge 5$,   and $\overline{W}= V(\omega_{n-1})$ or $\overline{W}=V(\omega_{n}) $ is a half-spin $\overline{\mathbb L}G$-module.
\item  \cref{prop:char2 list} (xi) or (xii) holds, $G = \Omega_{8}^+(q)$, and up to relabeling the fundamental weights by triality, and $\overline{W}=V(\omega_1)$ is a natural $\overline{\mathbb L}G$-module.
\end{enumerate}

\label{spin symplectic}
Assume that \cref{the new list} (ii)(b) holds.  Then either $n=2$ and $G$ acts transitively on $V^\#$ or $n = 3$, $\overline V=\overline W^{\sigma_1}$, $G \cong \mathrm{Sp}_6(q)$ and $ H \cong \Omega_6^-(q){:} 2$.
 Furthermore,   $G$ has $q$ orbits on the non-zero vectors of $V$. These orbits consist of \begin{enumerate}\item one orbit  of length $(q^{3}+1)(q^2+1)(q^2-1)$, with  point stabiliser  $O^{2'}(P_3)$ of shape $ q^{3+3}{:}\mathrm{SL}_3(q)$; and\item $q-1$   orbits of length $q^{3}(q^{4}-1)$ each  with point
 stabiliser $\mathrm G_2(q)$.\end{enumerate}

\label{prop:trans cases} Suppose that $G$ is a quasisimple group and $V$ is a non-trivial $\mathrm{GF}(2)G$-module.  Let $H$ be a maximal subgroup of $G$ and assume that $(G,H,V)$ is immutable with $H$ transitive on $V^\#$. Then one of the following holds.
\begin{enumerate}
\item  $G=\mathrm{SL}_n(2^a)$, $H$ normalizes $K=\mathrm{SL}_{n/b}(2^{ab})$ where $b$ is a prime which divides $n$ with $b<n$;
    \item  $G=\mathrm{SL}_n(2 )$, $H =\Gamma \mathrm L_1(2^n)$ with $n$  an odd prime;
\item   $G= \mathrm{SL}_{2m}(2^a)$, $H$ normalizes $K=\mathrm{Sp}_{2m}(2^a)$;
\item  $G=\mathrm{SL}_{4}(2)$, $H=\mathrm{Alt}(7)$;
\item   $G= \mathrm{Sp}_{2n}(2^a)$, $H$ normalizes $K=\mathrm{Sp}_{2n/b}(2^{ab})$ where $b$ is a prime which divides $n$;
\item  $G =\mathrm{Sp}_6(2^a)$, $H$ normalizes $K=\mathrm{G}_2(2^a)$;
\item  $G=  \mathrm{Alt}(7)$, $\dim V=4$, $H\cong \mathrm{Sp}_4(2)'\cong \mathrm{Alt}(6)$;
    \item  $G=  \mathrm{Alt}(7)$, $\dim V=4$, $H \cong \mathrm{SL}_2(4){:}2 \cong \mathrm{Sym}(5)$; or
\item  $G=  \mathrm{Alt}(6)$, $\dim V=4$, $H \cong \mathrm{SL}_2(4)$ acting naturally on $V$.
\end{enumerate}
Furthermore, in cases (i) to (vi), $V$ is the natural module for $G$.

\label{lem:spin yields irreducible}
Suppose that $G \cong \mathrm{Sp}_6(2^a)$, $V$ is a faithful $\mathrm{GF}(2)G$-module with no  centralized direct summands and $H$ is a maximal subgroup of $G$.
Assume that $V$ has a composition factor which is a spin module. If $(G,H,V)$ is immutable, then $V$ is irreducible.

\label{lem:sp2nq immutable struct}
  Suppose that $G\cong \mathrm{Sp}_{2n}(2^a)$, and let $\mathcal W$ be the $\mathrm{GF}(2)G$-module described in \cref{not:symp mod}. Assume that $H$ is a maximal subgroup of $G$. The triple $(G,H,\mathcal W)$ is immutable if and only if  one of the following holds:
  \begin{enumerate}
 \item  there exists an odd prime $b$ dividing $n$ and $H$ is conjugate to $\mathrm{Sp}_{2n/b}(2^{ab}){:b}$;
 \item $n=3$ and $H \cong \mathrm{G}_2(2^a)$.
 \end{enumerate}
 Furthermore, if $n$ is even, and  $H$ is conjugate to  $\mathrm{Sp}_{n}(2^{2a}){:}2$, then  for each $B \le C_{\mathcal W}(G)$, there exists  a uniquely determined $[{\mathcal W},G] \le B^\dagger \le {\mathcal W}$ with $\dim B^\dagger /B=a(2n+1)$ such that the faithful section $V= A/B$ satisfies $(G,H,V)$ is immutable if and only if $[{\mathcal W},G]\le A\le B^\dagger$.
